using Xunit;
using Xunit.v3;

[assembly: CollectionBehavior(typeof(MyApp.Tests.CustomCollectionFactory))]

namespace MyApp.Tests;

public class CustomCollectionFactory : TestCollectionFactoryBase
{
    public CustomCollectionFactory(IXunitTestAssembly testAssembly) : base(testAssembly) { }

    public override string DisplayName => "Custom Collection Factory";

    protected override IXunitTestCollection GetDefaultTestCollection(Type testClass)
    {
        return new XunitTestCollection(TestAssembly, null, false, testClass.Name, testClass.FullName ?? testClass.Name);
    }
}

public class DatabaseFixture : IDisposable
{
